   "    img.onload = () => resolve(img);\n    img.onerror = () => reject(new Error('No se pudo leer la imagen'));\n    img.src = src;\n  });\n}\n\n// ---------- Fondo fijo Mark·Inc ----------\n// El fondo vive en /static/cotizador_fondo.jpg. Si la foto de la unidad se\n// sube SIN fondo (PNG transparente), se monta sola sobre él, centrada abajo\n// dentro del marco. Así todas las unidades y colores quedan con el mismo\n// fondo sin editar nada a mano.\nconst CV_FONDO_URL = '/static/cotizador_fondo.jpg';\nlet CV_FONDO_DATAURL = null;\n\nasync function cv_fondoDataUrl() {\n  if (!CV_FONDO_DATAURL) {\n    const r = await fetch(CV_FONDO_URL);\n    if (!r.ok) throw new Error('No se encontró el fondo del cotizador (cotizador_fondo.jpg).');\n    const b = await r.blob();\n    CV_FONDO_DATAURL = await new Promise((res, rej) => {\n      const fr = new FileReader();\n      fr.onload = () => res(fr.result);\n      fr.onerror = () => rej(new Error('No se pudo leer el fondo'));\n      fr.readAsDataURL(b);\n    });\n  }\n  return CV_FONDO_DATAURL;\n}\n\n// Caja de lo que NO es transparente (en px de la imagen). null si la imagen\n// no trae transparencia (foto normal con fondo).\nfunction cv_cajaVisible(img) {\n  const esc = Math.min(1, 600 / Math.max(img.naturalWidth, img.naturalHeight));\n  const w = Math.max(1, Math.round(img.naturalWidth * esc)), h = Math.max(1, Math.round(img.naturalHeight * esc));\n  const c = document.createElement('canvas');\n  c.width = w; c.height = h;\n  const ctx = c.getContext('2d');\n  ctx.drawImage(img, 0, 0, w, h);\n  const d = ctx.getImageData(0, 0, w, h).data;\n  let transparentes = 0, x0 = w, y0 = h, x1 = -1, y1 = -1;\n  for (let y = 0; y < h; y++) {\n    for (let x = 0; x < w; x++) {\n      if (d[(y * w + x) * 4 + 3] < 20) { transparentes++; continue; }\n      if (x < x0) x0 = x;\n      if (x > x1) x1 = x;\n      if (y < y0) y0 = y;\n      if (y > y1) y1 = y;\n    }\n  }\n  if (transparentes < w * h * 0.02 || x1 < 0) return null;\n  return { x: x0 / esc, y: y0 / esc, w: (x1 - x0 + 1) / esc, h: (y1 - y0 + 1) / esc };\n}\n\nasync function cv_montarEnFondo(dataUrl) {\n  const [fondo, img] = await Promise.all([cv_cargarImagen(await cv_fondoDataUrl()), cv_cargarImagen(dataUrl)]);\n  const caja = cv_cajaVisible(img) || { x: 0, y: 0, w: img.naturalWidth, h: img.naturalHeight };\n  const W = fondo.naturalWidth, H = fondo.naturalHeight;\n  const area = { x: W * 0.06, y: H * 0.09, w: W * 0.88, h: H * 0.82 };\n  const esc = Math.min(area.w / caja.w, area.h / caja.h);\n  const w = caja.w * esc, h = caja.h * esc;\n  const c = document.createElement('canvas');\n  c.width = W; c.height = H;\n  const ctx = c.getContext('2d');\n  ctx.imageSmoothingQuality = 'high';\n  ctx.drawImage(fondo, 0, 0, W, H);\n  ctx.drawImage(img, caja.x, caja.y, caja.w, caja.h, area.x + (area.w - w) / 2, area.y + area.h - h, w, h);\n  return c.toDataURL('image/jpeg', 0.88);\n}\n\n// Pieza del equipo especial: se recorta a lo que se ve (sin el margen\n// transparente) para que el tamaño en el escenario sea el de la pieza.\nasync function cv_recortarVisible(dataUrl) {\n  const img = await cv_cargarImagen(dataUrl);\n  const caja = cv_cajaVisible(img);\n  if (!caja) return dataUrl;\n  const c = document.createElement('canvas');\n  c.width = Math.max(1, Math.round(caja.w)); c.height = Math.max(1, Math.round(caja.h));\n  c.getContext('2d').drawImage(img, caja.x, caja.y, caja.w, caja.h, 0, 0, c.width, c.height);\n  return cv_canvasAAccesorio(c);\n}\n\n// Foto principal o de un color: sin fondo (PNG) → se monta sobre el fondo\n// Mark·Inc; con fondo → como siempre (JPG con fondo blanco).\nasync function cv_leerFotoPrincipal(file) {\n  const conAlfa = await cv_leerArchivoImagen(file, 2400, false);\n  if (cv_cajaVisible(await cv_cargarImagen(conAlfa))) return await cv_montarEnFondo(conAlfa);\n  return await cv_leerArchivoImagen(file, 1600, true);\n}\n\n// Para fotos que ya estaban subidas con fondo blanco.\nasync function cv_ponerFondoMarkinc(dataUrl) {\n  const sinBlanco = await cv_quitarFondoBlanco(dataUrl);\n  if (!cv_cajaVisible(await cv_cargarImagen(sinBlanco))) {\n    throw new Error('No se pudo separar la unidad del fondo (la foto no tiene fondo blanco liso). Súbela ya sin fondo (PNG).');\n  }\n  return cv_montarEnFondo(sinBlanco);\n}\n\nasync function cv_fondoMarkincEn(destino, boton) {\n  const c = CV_EDIT.config;\n  const obj = destino === CV_BASE ? c.base : (c.colores || []).find(x => x.uid === destino);\n  if (!obj || !obj.imagen) return;\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      obj.imagen = await cv_ponerFondoMarkinc(obj.imagen);\n      cv_renderEditor();\n    } catch (e) { alert(e.message); }\n  });\n}\n\n"
