   "      cv_renderCotizar();\n      const aviso = document.getElementById('cv_creada');\n      if (aviso) aviso.scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n    } catch (e) { alert(e.message); }\n  });\n}\n\n// ---------- Equipo especial (cotizar) ----------\n// config.tipo = 'escena': el fondo Mark·Inc es la \"foto principal\" (sin\n// precio) y cada accesorio es una PIEZA con su \"lugar\" (Unidad, Compresor…;\n// se guarda también como grupo, así que de un lugar solo va una pieza).\n// Cada pieza tiene foto mirando a la derecha (imagen, x, y, w, rot) y a la\n// izquierda (imagen_izq, xi, yi, wi, roti). El vendedor elige el lado por lugar.\n\nfunction cv_esc_lugarKey(a) {\n  return ((a.lugar || a.grupo || '').trim().toLowerCase()) || a.uid;\n}\n\nfunction cv_esc_vista(cfg) {\n  const lados = (CV_SEL && CV_SEL.lado) || {};\n  return {\n    ...cfg,\n    accesorios: cfg.accesorios.map(a => (lados[cv_esc_lugarKey(a)] === 'izq' && a.imagen_izq)\n      ? { ...a, imagen: a.imagen_izq, x: a.xi ?? a.x, y: a.yi ?? a.y, w: a.wi ?? a.w, rot: a.roti ?? a.rot }\n      : a),\n  };\n}\n\nfunction cv_esc_lugares(cfg) {\n  const lugares = [];\n  cfg.accesorios.forEach(a => {\n    const k = cv_esc_lugarKey(a);\n    let g = lugares.find(x => x.k === k);\n    if (!g) { g = { k, nombre: (a.lugar || a.grupo || '').trim() || a.nombre, piezas: [] }; lugares.push(g); }\n    g.piezas.push(a);\n  });\n  return lugares;\n}\n\nfunction cv_esc_setLado(i, lado) {\n  const g = cv_esc_lugares(CV_KIT.config)[i];\n  if (!g) return;\n  CV_SEL.lado[g.k] = lado;\n  cv_renderCotizar();\n}\n\nfunction cv_esc_htmlPiezas(cfg) {\n  return cv_esc_lugares(cfg).map((g, i) => {\n    const conIzq = g.piezas.some(a => a.imagen_izq);\n    const lado = (CV_SEL.lado || {})[g.k] === 'izq' ? 'izq' : 'der';\n    return `\n      <div style=\"display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin:12px 0 6px;\">\n        <b style=\"font-size:13px; flex:1;\">${escapeHtml(g.nombre)}</b>\n        ${conIzq ? `<div style=\"display:flex; gap:4px;\">\n          <button type=\"button\" class=\"${lado === 'izq' ? 'primary' : 'secondary'}\" style=\"padding:4px 10px; font-size:12px;\" onclick=\"cv_esc_setLado(${i}, 'izq')\">◀ Izquierda</button>\n          <button type=\"button\" class=\"${lado === 'der' ? 'primary' : 'secondary'}\" style=\"padding:4px 10px; font-size:12px;\" onclick=\"cv_esc_setLado(${i}, 'der')\">Derecha ▶</button>\n        </div>` : ''}\n      </div>\n      ${g.piezas.map(a => {\n        const on = CV_SEL.activos.includes(a.uid);\n        const precio = Number(CV_SEL.precio[a.uid] ?? a.precio) || 0;\n        const foto = (lado === 'izq' && a.imagen_izq) ? a.imagen_izq : a.imagen;\n        return `\n        <div class=\"cv-acc${on ? ' on' : ''}\" onclick=\"cv_toggleAccesorio('${a.uid}')\">\n          <div class=\"cv-thumb\">${foto ? `<img src=\"${foto}\" alt=\"\" />` : '📦'}</div>\n          <div style=\"flex:1; min-width:0;\">\n            <div style=\"display:flex; gap:6px; align-items:center;\">\n              <span style=\"font-weight:600; font-size:13px; flex:1;\">${escapeHtml(a.nombre)}</span>\n              <span style=\"font-size:18px;\">${on ? '✅' : '➕'}</span>\n            </div>\n            ${on ? cv_htmlLineaPrecio(a.uid, a, true) : `<div style=\"font-size:12px; color:var(--muted); margin-top:4px;\">$${cot_fmt(precio)}</div>`}\n          </div>\n        </div>`;\n      }).join('')}`;\n  }).join('');\n}\n\n// ---------- Equipo especial (editor) ----------\n\n// Intercambia el lado que se está acomodando: la foto y la posición del otro\n// lado pasan a \"imagen/x/y/w/rot\" para reutilizar el mismo editor de capas.\nfunction cv_esc_swap(cfg) {\n  (cfg.accesorios || []).forEach(a => {\n    if (a.xi == null) { a.xi = a.x; a.yi = a.y; a.wi = a.w; a.roti = a.rot || 0; }\n    [a.imagen, a.imagen_izq] = [a.imagen_izq || null, a.imagen || null];\n    [a.x, a.xi] = [a.xi, a.x];\n    [a.y, a.yi] = [a.yi, a.y];\n    [a.w, a.wi] = [a.wi, a.w];\n    [a.rot, a.roti] = [a.roti, a.rot];\n  });\n}\n\nfunction cv_esc_verLado(lado) {\n  if (lado === CV_EDIT_LADO) return;\n  cv_esc_swap(CV_EDIT.config);\n  CV_EDIT_LADO = lado;\n  CV_DESHACER = {};\n  cv_renderEditor();\n}\n\nfunction cv_esc_renderEditor() {\n  const cont = document.getElementById('checadorPrecioContenido');\n  const k = CV_EDIT, c = k.config;\n  const todos = c.accesorios.map(a => a.uid);\n  const ladoTxt = CV_EDIT_LADO === 'izq' ? 'izquierda' : 'derecha';\n  const lugares = [...new Set(c.accesorios.map(a => (a.lugar || '').trim()).filter(Boolean))];\n  const sugeridos = ['Unidad', 'Compresor', 'Monitor', 'Lámpara', 'Banco'].filter(x => !lugares.includes(x));\n  cont.innerHTML = `\n    <div style=\"display:flex; justify-content:space-between; align-items:center; gap:10px; margin-bottom:12px; flex-wrap:wrap;\">\n      <h3 style=\"margin:0;\">${k.id ? 'Editar equipo especial' : 'Nuevo equipo especial'}</h3>\n      <button class=\"secondary\" onclick=\"if(confirm('¿Salir sin guardar los cambios?')) cv_renderLista();\">← Equipos</button>\n    </div>\n    <div class=\"row-2\">\n      <div class=\"field\"><label>Nombre del equipo *</label>\n        <input value=\"${escapeHtml(k.nombre || '')}\" placeholder=\"ej. Arma tu consultorio\" oninput=\"CV_EDIT.nombre=this.value\" /></div>\n      <div class=\"field\"><label>Visible para vendedores</label>\n        <label style=\"text-transform:none; font-weight:400; display:flex; gap:6px; align-items:center; margin-top:8px;\">\n          <input type=\"checkbox\" class=\"cv-check\" ${k.activo ? 'checked' : ''} onchange=\"CV_EDIT.activo=this.checked\" /> Activo (si lo apagas, solo tú lo ves)</label></div>\n    </div>\n    <div class=\"cv-caja\" style=\"font-size:12px; color:var(--muted);\">\n      El fondo Mark·Inc es fijo. Cada pieza (unidad, compresor, monitor…) va en un <b>lugar</b>: de un mismo lugar el vendedor elige solo una.\n      Sube cada pieza <b>sin fondo (PNG)</b> mirando a la <b>derecha</b> y a la <b>izquierda</b>; cada lado tiene su propia posición.\n      Las marcadas \"viene seleccionada\" aparecen puestas al abrir el equipo.\n    </div>\n\n    <span class=\"cv-etq\">1 · Acomoda las piezas — lado que estás viendo: <b style=\"color:var(--text);\">${ladoTxt}</b></span>\n    <div style=\"display:flex; gap:6px; margin-bottom:8px; flex-wrap:wrap;\">\n      <button class=\"${CV_EDIT_LADO === 'izq' ? 'primary' : 'secondary'}\" onclick=\"cv_esc_verLado('izq')\">◀ Mirando a la izquierda</button>\n      <button class=\"${CV_EDIT_LADO === 'der' ? 'primary' : 'secondary'}\" onclick=\"cv_esc_verLado('der')\">Mirando a la derecha ▶</button>\n    </div>\n    <div class=\"cv-layout\">\n      <div>\n        <div class=\"cv-stage editando\" id=\"cv_stage_edit\">${cv_htmlStage(c, todos, true)}</div>\n        <p style=\"font-size:11px; color:var(--muted); margin-top:6px;\">Aquí se ven todas las piezas juntas para acomodarlas; al cotizar sale solo una por lugar.</p>\n      </div>\n      <div class=\"cv-caja\" id=\"cv_ctrl_capa\">${cv_htmlControlesCapa()}</div>\n    </div>\n\n    <datalist id=\"cv_lugares\">${[...lugares, ...sugeridos].map(l => `<option value=\"${escapeHtml(l)}\"></option>`).join('')}</datalist>\n    <span class=\"cv-etq\">2 · Piezas</span>\n    ${c.accesorios.map(a => {\n      const fotoDer = CV_EDIT_LADO === 'der' ? a.imagen : a.imagen_izq;\n      const fotoIzq = CV_EDIT_LADO === 'izq' ? a.imagen : a.imagen_izq;\n      return `\n      <div class=\"cv-caja\" style=\"${a.uid === CV_EDIT_SEL ? 'border-color:var(--copper);' : ''}\">\n        <div class=\"row-2\">\n          <div class=\"field\"><label>Lugar * (ej. Unidad, Compresor)</label>\n            <input list=\"cv_lugares\" value=\"${escapeHtml(a.lugar || '')}\" placeholder=\"Unidad\" oninput=\"cv_setProd('${a.uid}','lugar',this.value)\" /></div>\n          <div class=\"field\"><label>Al abrir el equipo</label>\n            <label style=\"text-transform:none; font-weight:400; display:flex; gap:6px; align-items:center; margin-top:8px;\">\n              <input type=\"checkbox\" class=\"cv-check\" ${a.por_defecto ? 'checked' : ''} onchange=\"cv_setProd('${a.uid}','por_defecto',this.checked)\" /> Viene seleccionada</label></div>\n        </div>\n        <div style=\"display:flex; gap:10px; align-items:center; margin-bottom:8px; flex-wrap:wrap;\">\n          <div style=\"text-align:center;\"><div class=\"cv-thumb\" style=\"width:70px; height:70px;\">${fotoIzq ? `<img src=\"${fotoIzq}\" alt=\"\" />` : '—'}</div><div style=\"font-size:10px; color:var(--muted);\">◀ izquierda</div></div>\n          <div style=\"text-align:center;\"><div class=\"cv-thumb\" style=\"width:70px; height:70px;\">${fotoDer ? `<img src=\"${fotoDer}\" alt=\"\" />` : '—'}</div><div style=\"font-size:10px; color:var(--muted);\">derecha ▶</div></div>\n          <div style=\"display:flex; gap:6px; flex-wrap:wrap; flex:1;\">\n            <button type=\"button\" class=\"secondary\" onclick=\"cv_elegirFoto('${a.uid}', 'izq')\">📷 ${fotoIzq ? 'Cambiar' : 'Subir'} foto izquierda</button>\n            <button type=\"button\" class=\"secondary\" onclick=\"cv_elegirFoto('${a.uid}', 'der')\">📷 ${fotoDer ? 'Cambiar' : 'Subir'} foto derecha</button>\n            ${a.imagen ? `<button type=\"button\" class=\"secondary\" onclick=\"cv_quitarFondo('${a.uid}', this)\">✨ Quitar fondo blanco (${ladoTxt})</button>` : ''}\n            ${CV_DESHACER[a.uid] ? `<button type=\"button\" class=\"secondary\" onclick=\"cv_deshacerFondo('${a.uid}')\">↩️ Deshacer</button>` : ''}\n            ${a.imagen ? `<button type=\"button\" class=\"secondary\" onclick=\"cv_seleccionarCapa('${a.uid}')\">📍 Acomodar (${ladoTxt})</button>` : ''}\n          </div>\n          <button type=\"button\" class=\"secondary\" style=\"color:var(--copper); border-color:var(--copper);\" onclick=\"cv_quitarAccesorio('${a.uid}')\">✕ Quitar</button>\n        </div>\n        ${cv_htmlProductoEditor(a.uid)}\n      </div>`;\n    }).join('')}\n    <button type=\"button\" class=\"secondary\" onclick=\"cv_agregarAccesorio()\">+ Agregar pieza</button>\n\n    <div style=\"display:flex; gap:8px; margin-top:22px; flex-wrap:wrap;\">\n      <button class=\"primary\" style=\"flex:1; min-width:180px;\" onclick=\"cv_guardarKit(this)\">💾 Guardar equipo</button>\n      ${k.id ? `<button class=\"secondary\" style=\"color:var(--copper); border-color:var(--copper);\" onclick=\"cv_eliminarKit()\">🗑️ Eliminar equipo</button>` : ''}\n    </div>\n  `;\n  cv_activarArrastre();\n}\n\nasync function cv_esc_guardar(boton) {\n  const k = CV_EDIT;\n  // copia en orden \"derecha\" (lo que se guarda), sin tocar lo que se está viendo\n  const c = JSON.parse(JSON.stringify(k.config));\n  if (CV_EDIT_LADO === 'izq') cv_esc_swap(c);\n  if (!(k.nombre || '').trim()) { alert('Ponle nombre al equipo.'); return; }\n  if (!c.accesorios.length) { alert('Agrega al menos una pieza (ej. la unidad).'); return; }\n  const sinNombre = c.accesorios.find(a => !(a.nombre || '').trim());\n  if (sinNombre) { alert('Hay una pieza sin nombre — escríbele nombre o quítala.'); return; }\n  const sinLugar = c.accesorios.find(a => !(a.lugar || '').trim());\n  if (sinLugar) { alert(`A \"${sinLugar.nombre}\" le falta el lugar (ej. Unidad, Compresor).`); return; }\n  const sinFoto = c.accesorios.find(a => !a.imagen && !a.imagen_izq);\n  if (sinFoto) { alert(`A \"${sinFoto.nombre}\" le falta su foto.`); return; }\n  c.accesorios.forEach(a => {\n    a.lugar = a.lugar.trim();\n    a.grupo = a.lugar;\n    if (!a.imagen && a.imagen_izq) {   // solo subieron la de la izquierda: se usa en los dos lados\n      a.imagen = a.imagen_izq; a.x = a.xi ?? a.x; a.y = a.yi ?? a.y; a.w = a.wi ?? a.w; a.rot = a.roti ?? a.rot;\n      a.imagen_izq = null;\n    }\n  });\n  c.base = { ...cv_productoVacio(), ...c.base, nombre: k.nombre.trim(), precio: 0, imagen: await cv_fondoDataUrl() };\n  const tamano = JSON.stringify(c).length;\n  if (tamano > 19000000) { alert(`Las fotos de este equipo pesan demasiado en total (${Math.round(tamano / 1e6)}MB). Usa menos piezas o fotos más ligeras.`); return; }\n  const puestos = new Set(), activos = [];\n  c.accesorios.filter(a => a.por_defecto).forEach(a => { const g = cv_esc_lugarKey(a); if (!puestos.has(g)) { puestos.add(g); activos.push(a.uid); } });\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      const payload = { nombre: k.nombre.trim(), activo: !!k.activo, miniatura: await cv_miniatura(c, activos), config: c };\n      const r = k.id\n        ? await api(`/api/cotizador-visual/kits/${k.id}`, { method: 'PUT', body: JSON.stringify(payload) })\n        : await api('/api/cotizador-visual/kits', { method: 'POST', body: JSON.stringify(payload) });\n      CV_EDIT.id = r.id;\n      await cv_renderLista();\n    } catch (e) { alert(e.message); }\n  });\n}\n"
